// Deterministic offline rows from the checked-in source, without relying on
// ignored output generated by another test or an earlier database run.
import {readFileSync} from 'node:fs';

export function attachmentCatalogFixture() {
  const bundle=JSON.parse(readFileSync(new URL('../../database/attachment-v2/generated/attachment-bundle.json',import.meta.url),'utf8'));
  const rules=new Map(bundle.rules.map(rule=>[rule.import_key,rule]));
  return {items:bundle.catalog.map((row,index)=>({...row,attachment_price_id:index+1,
    category_level3:'',rules:bundle.bindings.filter(binding=>binding.attachment_key===row.import_key)
      .map(binding=>structuredClone(rules.get(binding.rule_key)))}))};
}
